from functools import cmp_to_key


def _parse(version):
    # Build metadata is ignored for precedence.
    version = version.split('+', 1)[0]
    if '-' in version:
        core, prerelease = version.split('-', 1)
        pre = prerelease.split('.') if prerelease != '' else []
    else:
        core, pre = version, None
    major, minor, patch = (int(part) for part in core.split('.'))
    return (major, minor, patch), pre


def _compare_identifiers(a, b):
    a_numeric = a.isdigit()
    b_numeric = b.isdigit()
    if a_numeric and b_numeric:
        ai, bi = int(a), int(b)
        return (ai > bi) - (ai < bi)
    if a_numeric:
        return -1
    if b_numeric:
        return 1
    return (a > b) - (a < b)


def _compare_versions(a, b):
    core_a, pre_a = _parse(a)
    core_b, pre_b = _parse(b)

    if core_a != core_b:
        return (core_a > core_b) - (core_a < core_b)

    # A version without a pre-release has higher precedence.
    if pre_a is None and pre_b is None:
        return 0
    if pre_a is None:
        return 1
    if pre_b is None:
        return -1

    for id_a, id_b in zip(pre_a, pre_b):
        cmp = _compare_identifiers(id_a, id_b)
        if cmp:
            return cmp
    return (len(pre_a) > len(pre_b)) - (len(pre_a) < len(pre_b))


def sort_versions(vs):
    return sorted(vs, key=cmp_to_key(_compare_versions))
